import{c as r,Q as n,j as a,m as t}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Harnesses for Inference-Time Alignment over Execution Trajectories","description":"","frontmatter":{"url":"https://arxiv.org/abs/2605.21516","title":"Harnesses for Inference-Time Alignment over Execution Trajectories","archived_date":"2026-07-18T00:00:00.000Z","arxiv_id":2605.21516,"authors":["Boyuan Wang","Bochao Li","Minghan Wang","Yuxin Tao","Fang Kong"],"pdf_path":"pdfs/2605.21516.pdf","published_date":"2026-05-15T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-05-15-harnesses-inference-time-alignment-trajectories-2605-21516.md","filePath":"research/papers/2026-05-15-harnesses-inference-time-alignment-trajectories-2605-21516.md","lastUpdated":1785909234000}'),i={name:"research/papers/2026-05-15-harnesses-inference-time-alignment-trajectories-2605-21516.md"};function s(o,e,c,h,l,g){return n(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="harnesses-for-inference-time-alignment-over-execution-trajectories" tabindex="-1">Harnesses for Inference-Time Alignment over Execution Trajectories <a class="header-anchor" href="#harnesses-for-inference-time-alignment-over-execution-trajectories" aria-label="Permalink to &quot;Harnesses for Inference-Time Alignment over Execution Trajectories&quot;">​</a></h1><p><strong>Authors</strong>: Boyuan Wang, Bochao Li, Minghan Wang, Yuxin Tao, Fang Kong <strong>Published</strong>: May 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2605.21516" target="_blank" rel="noreferrer">https://arxiv.org/abs/2605.21516</a><strong>arXiv ID</strong>: 2605.21516 <strong>Categories</strong>: Machine Learning (cs.LG); Artificial Intelligence (cs.AI) <strong>PDF</strong>: <a href="https://arxiv.org/abs/2605.21516" target="_blank" rel="noreferrer">research/papers/pdfs/2605.21516.pdf</a></p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>The paper examines how workflow engineering enhances LLM agent performance through inference-time techniques. The researchers note that increasing decomposition or guidance can sometimes improve execution, but can also reduce final task success. They analyze harness design by studying trajectory alignment, distinguishing between task decomposition (structuring tasks into sub-goals) and guided execution (reshaping action distributions). Their framework identifies performance constraints linked to workflow granularity, retry budgets, and action reweighting, while revealing failure patterns including over-decomposition, over-pruning, and hallucinated execution. The work validates these insights through synthetic experiments and real agent benchmarks, ultimately demonstrating that effective harnesses can be partial: specifying only the initial steps and leaving the remaining execution to agent can achieve higher pass rate than fully structured workflows.</p><hr><h2 id="core-thesis" tabindex="-1">Core Thesis <a class="header-anchor" href="#core-thesis" aria-label="Permalink to &quot;Core Thesis&quot;">​</a></h2><ul><li>拆解 harness 對 execution trajectory 的兩種介入方式：task decomposition（拆解成子目標）與 guided execution（重塑動作分佈），並指出「越多分解／引導 = 越好」是假設而非事實——過度分解、過度剪枝反而降低任務成功率。</li><li>提出 workflow granularity、retry budget、action reweighting 三個效能制約維度，並整理三種失敗模式：over-decomposition、over-pruning、hallucinated execution。</li><li>關鍵發現：<strong>partial harness</strong>（只規範初始步驟，其餘交給 agent 自主執行）在合成實驗與真實 benchmark 上通過率優於全結構化 workflow——顯示「過度工程化」的 harness 反而有害。</li><li><strong>Workspace 關聯</strong>：直接挑戰「儀式構件越多越好」的直覺，與 core.md「儀式深度隨風險伸縮、不隨模型檔位」的立場互補——為高能力模型設計 harness 時應保留部分自主空間而非全鏈路硬編排，可作為 <code>/fusion</code> sidekick brief 顆粒度設計的參考證據。</li></ul>',8)])])}const p=r(i,[["render",s]]);export{u as __pageData,p as default};
